class WordDistance:
    def __init__(self, words_dict):
        self.words = words_dict

    def shortest(self, word1, word2):
        idx1 = idx2 = -1
        best = float('inf')
        for i, w in enumerate(self.words):        # scan the entire array every call
            if w == word1:
                idx1 = i
            elif w == word2:
                idx2 = i
            if idx1 != -1 and idx2 != -1:
                best = min(best, abs(idx1 - idx2))
        return best

