public class WordDistance {
    String[] words;

    WordDistance(String[] wordsDict) {
        words = wordsDict;
    }

    int shortest(String word1, String word2) {
        int idx1 = -1, idx2 = -1, best = Integer.MAX_VALUE;
        for (int i = 0; i < words.length; i++) {         // scan the entire array every call
            if (words[i].equals(word1)) idx1 = i;
            else if (words[i].equals(word2)) idx2 = i;
            if (idx1 != -1 && idx2 != -1) best = Math.min(best, Math.abs(idx1 - idx2));
        }
        return best;
    }
}

