from collections import defaultdict

class WordDistance:
    def __init__(self, words_dict):
        self.index = defaultdict(list)
        for i, w in enumerate(words_dict):
            self.index[w].append(i)                # precompute once, at construction

    def shortest(self, word1, word2):
        a, b = self.index[word1], self.index[word2]
        i = j = 0
        best = float('inf')
        while i < len(a) and j < len(b):           # two-pointer merge over the index lists
            best = min(best, abs(a[i] - b[j]))
            if a[i] < b[j]:
                i += 1
            else:
                j += 1
        return best

