import java.util.*;

public class WordDistance {
    Map<String, List<Integer>> index = new HashMap<>();

    WordDistance(String[] wordsDict) {
        for (int i = 0; i < wordsDict.length; i++) {
            index.computeIfAbsent(wordsDict[i], k -> new ArrayList<>()).add(i);   // precompute once
        }
    }

    int shortest(String word1, String word2) {
        List<Integer> a = index.get(word1), b = index.get(word2);
        int i = 0, j = 0, best = Integer.MAX_VALUE;
        while (i < a.size() && j < b.size()) {         // two-pointer merge over the index lists
            best = Math.min(best, Math.abs(a.get(i) - b.get(j)));
            if (a.get(i) < b.get(j)) i++; else j++;
        }
        return best;
    }
}

